import urllib.request, json, os, re

api_key = os.environ.get('DEEPSEEK_API_KEY', '')

# Read report
report_content = open('raw/notebooklm-analysis/Harness-实践-Agent-全自动知识讲解视频生成技术简报.md').read()

# Build existing_wiki string - empty for fresh build
existing_wiki = '（暂无已有页面）'

prompt = '''你是知识图谱分析专家。从以下视频分析报告中提取所有实体和概念，并与现有 wiki 清单做语义去重。

## 现有 wiki 页面（去重参考）
{existing_wiki}

## 分析报告
{report}

## 任务
1. 提取所有值得建页的实体（人物/组织/产品/工具/平台）和概念（技术概念/方法论/架构思想）
2. 对每项判断：new=新建 / merge=合并到已有页（语义相同）/ skip=太泛不值得建页
3. 实体和概念各自去重（同一事物只保留一个规范名称）

## 输出格式（严格 JSON，不要任何注释）
{{
  \"source\": {{
    \"title\": \"源页面标题\",
    \"slug\": \"文件名slug（英文+中文，无空格，用连字符）\"
  }},
  \"entities\": [
    {{\"name\": \"规范名称\", \"slug\": \"文件名\", \"action\": \"new|merge|skip\", \"merge_target\": \"已有文件名或null\", \"reason\": \"一句话\"}}
  ],
  \"concepts\": [
    {{\"name\": \"规范名称\", \"slug\": \"文件名\", \"action\": \"new|merge|skip\", \"merge_target\": \"已有文件名或null\", \"reason\": \"一句话\"}}
  ]
}}'''.format(existing_wiki=existing_wiki, report=report_content[:6000])

payload = json.dumps({
    'model': 'deepseek-v4-flash',
    'messages': [{'role': 'user', 'content': prompt}],
    'max_tokens': 3000,
    'temperature': 0.2,
}).encode()

req = urllib.request.Request(
    'https://api.deepseek.com/v1/chat/completions', data=payload,
    headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {api_key}'}
)
with urllib.request.urlopen(req, timeout=120) as resp:
    data = json.loads(resp.read())

text = data['choices'][0]['message']['content']
print('=== RAW RESPONSE (first 2000 chars) ===')
print(text[:2000])
print('=== ... ===')
print(f'Total length: {len(text)}')
usage = data.get('usage', {})
print(f'Tokens: prompt={usage.get(\"prompt_tokens\")} completion={usage.get(\"completion_tokens\")}')
" 2>&1", "timeout": 120}

